<?php
use App\Domain\Tenancy\TenantContext;
use App\Domain\Operations\{ReturnService,CashService,Conflict};
require __DIR__.'/phase-6-7-stage.php';
try{$jobPath=realpath($argv[1]??'');$root=realpath(__DIR__.'/../docs/audit/private');if(!$jobPath||!str_starts_with($jobPath,$root.DIRECTORY_SEPARATOR.'phase67-run-')||!preg_match('/job-[a-f0-9]+\.json$/D',$jobPath))throw new RuntimeException('Invalid worker fixture.');$job=json_decode(file_get_contents($jobPath),true,512,JSON_THROW_ON_ERROR);$result=app(TenantContext::class)->runFor($job['tenant'],$job['owner'],function()use($job,$jobPath){\Illuminate\Support\Facades\Auth::guard('web')->setUser(\App\Models\User::findOrFail($job['owner']));file_put_contents($jobPath.'.ready','ready');$deadline=microtime(true)+30;while(!is_file(dirname($jobPath).'/start')){if(microtime(true)>$deadline)throw new RuntimeException('Barrier timeout.');usleep(10000);}return match($job['operation']){'return'=>app(ReturnService::class)->post($job['source_id']),'refund'=>app(ReturnService::class)->refund($job['source_id'],$job['input']),'close'=>app(CashService::class)->close($job['source_id'],$job['input']),'product'=>app(\App\Http\Controllers\Api\V1\ProductApiController::class)->store(\Illuminate\Http\Request::create('/api/v1/products','POST',$job['input']))->getData(true),default=>throw new RuntimeException('Unknown worker action.')};});echo json_encode(['status'=>'ok','result'=>$result],JSON_THROW_ON_ERROR);}catch(Conflict $e){echo json_encode(['status'=>'conflict','message'=>$e->getMessage()]);}catch(Throwable $e){echo json_encode(['status'=>'error','class'=>$e::class,'message'=>$e->getMessage()]);exit(1);}
